-- Canonical reference data is public-read only; personal tables use auth.uid() policies.
create table evidence_sources (id text primary key, title text not null, organization text, url text, publication_year int, source_type text not null, population text, notes text);
create table nutrients (id uuid primary key default gen_random_uuid(), canonical_key text unique not null, name text not null, category text not null, default_unit text not null, description text, is_targetable boolean not null default true);
create table nutrient_forms (id uuid primary key default gen_random_uuid(), nutrient_id uuid not null references nutrients(id), form_key text unique not null, form_name text not null, origin_type text not null check (origin_type in ('animal','plant','supplement')), is_preformed boolean not null default false, is_precursor boolean not null default false, is_supplement_form boolean not null default false);
create table foods (id uuid primary key default gen_random_uuid(), name text not null, category text not null, brand text, description text, created_at timestamptz not null default now());
create table food_nutrients (food_id uuid references foods(id) on delete cascade, nutrient_form_id uuid references nutrient_forms(id), amount_per_100g numeric not null check(amount_per_100g >= 0), unit text not null, basis text not null default 'edible_portion', evidence_id text references evidence_sources(id), confidence text not null, primary key(food_id,nutrient_form_id));
create table preparation_methods (id uuid primary key default gen_random_uuid(), method_key text unique not null, name text not null, description text);
create table food_preparation_profiles (food_id uuid references foods(id), preparation_method_id uuid references preparation_methods(id), yield_factor_min numeric not null check(yield_factor_min > 0), yield_factor_max numeric not null check(yield_factor_max >= yield_factor_min), evidence_id text references evidence_sources(id), notes text, primary key(food_id, preparation_method_id));
create table retention_factors (id uuid primary key default gen_random_uuid(), food_id uuid references foods(id), preparation_method_id uuid not null references preparation_methods(id), nutrient_id uuid not null references nutrients(id), retention_min numeric not null check(retention_min >= 0), retention_max numeric not null check(retention_max >= retention_min), evidence_id text references evidence_sources(id));
create table targets (id uuid primary key default gen_random_uuid(), nutrient_id uuid not null references nutrients(id), reference_system text not null, reference_type text not null check(reference_type in ('rda','ai','pri','ear','optimal_min','optimal_max','ul')), sex text, age_min int, age_max int, life_stage text, value numeric not null check(value >= 0), unit text not null, evidence_id text references evidence_sources(id));
create table interactions (id uuid primary key default gen_random_uuid(), target_nutrient_id uuid not null references nutrients(id), effector_key text not null, mathematical_form text not null, parameters_json jsonb not null, min_multiplier numeric not null check(min_multiplier > 0), max_multiplier numeric not null check(max_multiplier >= min_multiplier), conditions_json jsonb not null default '{}'::jsonb, mechanism text not null, confidence text not null, evidence_id text references evidence_sources(id));
create table supplements (id uuid primary key default gen_random_uuid(), name text not null, manufacturer text, notes text);
create table supplement_components (supplement_id uuid references supplements(id) on delete cascade, nutrient_form_id uuid references nutrient_forms(id), label_amount numeric not null check(label_amount >= 0), elemental_amount numeric check(elemental_amount >= 0), unit text not null, evidence_id text references evidence_sources(id), primary key(supplement_id,nutrient_form_id));
create table user_profiles (user_id uuid primary key references auth.users(id) on delete cascade, sex text, age int check(age >= 0), body_weight_kg numeric check(body_weight_kg > 0), height_cm numeric check(height_cm > 0), energy_target_kcal numeric check(energy_target_kcal > 0), clinical_context_json jsonb not null default '{}'::jsonb);
create table meal_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, logged_on date not null, meal_slot text, notes text, created_at timestamptz not null default now());
create table meal_items (id uuid primary key default gen_random_uuid(), meal_id uuid not null references meal_logs(id) on delete cascade, food_id uuid not null references foods(id), preparation_method_id uuid references preparation_methods(id), weight_grams numeric not null check(weight_grams >= 0), weight_basis text not null check(weight_basis in ('raw','cooked')));
create table biomarker_results (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, marker_key text not null, tested_on date not null, value numeric not null, unit text not null, lab_low numeric, lab_high numeric, notes text);
create table user_target_overrides (user_id uuid references auth.users(id) on delete cascade, nutrient_id uuid references nutrients(id), custom_value numeric not null check(custom_value >= 0), unit text not null, notes text, primary key(user_id,nutrient_id));
alter table user_profiles enable row level security; alter table meal_logs enable row level security; alter table meal_items enable row level security; alter table biomarker_results enable row level security; alter table user_target_overrides enable row level security;
create policy "own profile" on user_profiles for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own meals" on meal_logs for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own meal items" on meal_items for all using (exists (select 1 from meal_logs m where m.id = meal_id and m.user_id = auth.uid())) with check (exists (select 1 from meal_logs m where m.id = meal_id and m.user_id = auth.uid()));
create policy "own biomarkers" on biomarker_results for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own overrides" on user_target_overrides for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
